23	export const GameResultForm = ({
24	    gameDayId,
25	    bibs,
26	    winners,
27	    setGameResult,
28	}: GameResultFormProps) => {
29	    const router = useRouter();
30	    const [isSaving, { open: setSaving, close: setSaved }] =
31	        useDisclosure(false);
32	    const form = useForm<{
33	        bibs: 'A' | 'B' | 'none';
34	        winner: 'A' | 'B' | 'draw' | 'none';
35	    }>({
36	        initialValues: {
37	            bibs: bibs ?? 'none',
38	            winner: winners ?? 'none',
39	        },
40	    });
41	
42	    const handleSave = async (values: {
43	        bibs: 'A' | 'B' | 'none';
44	        winner: 'A' | 'B' | 'draw' | 'none';
45	    }) => {
46	        const notificationId = 'game-result-update';
47	        notifications.show({
48	            id: notificationId,
49	            loading: true,
50	            title: 'Updating game details',
51	            message: 'Saving bibs and result...',
52	            autoClose: false,
53	            withCloseButton: false,
54	        });
55	
56	        setSaving();
57	        try {
58	            await setGameResult({
59	                gameDayId,
60	                bibs: values.bibs === 'none' ? null : values.bibs,
61	                winner: values.winner === 'none' ? null : values.winner,
62	            });
63	
64	            notifications.update({
65	                id: notificationId,
66	                color: 'teal',
67	                title: 'Game updated',
68	                message: 'Bibs and result were updated.',
69	                icon: <IconCheck size={config.notificationIconSize} />,
70	                loading: false,
71	                autoClose: config.notificationAutoClose,
72	            });
73	
74	            form.resetDirty(values);
75	            router.refresh();
76	        } catch (err) {
77	            const errorMessage =
78	                err instanceof Error ? err.message : 'Failed to update game';
79	            notifications.update({
80	                id: notificationId,
81	                color: 'red',
82	                title: 'Error',
83	                message: errorMessage,
84	                icon: <IconAlertTriangle size={config.notificationIconSize} />,
85	                loading: false,
86	                autoClose: false,
87	                withCloseButton: true,
88	            });
89	        } finally {
90	            setSaved();
91	        }
92	    };
93	
94	    return (
95	        <Box
96	            component="form"
97	            onSubmit={form.onSubmit(handleSave)}
98	        >
99	            <Paper
100	                p="md"
101	                radius="md"
102	            >
103	                <Flex
104	                    gap="sm"
105	                    wrap="wrap"
106	                    align="flex-end"
107	                >
108	                    <Select
109	                        label="Bibs"
110	                        data={[
111	                            { value: 'none', label: 'Not set' },
112	                            { value: 'A', label: 'Team A' },
113	                            { value: 'B', label: 'Team B' },
114	                        ]}
115	                        value={form.values.bibs}
116	                        /* v8 ignore next -- allowDeselect={false} means value is never null */
117	                        onChange={(value) =>
118	                            form.setFieldValue('bibs', value ?? 'none')
119	                        }
120	                        allowDeselect={false}
121	                        miw="8rem"
122	                    />
123	                    <Select
124	                        label="Result"
125	                        data={[
126	                            { value: 'none', label: 'Not set' },
127	                            { value: 'A', label: 'A won' },
128	                            { value: 'draw', label: 'Draw' },
129	                            { value: 'B', label: 'B won' },
130	                        ]}
131	                        value={form.values.winner}
132	                        /* v8 ignore next -- allowDeselect={false} means value is never null */
133	                        onChange={(value) =>
134	                            form.setFieldValue('winner', value ?? 'none')
135	                        }
136	                        allowDeselect={false}
137	                        miw="8rem"
138	                    />
139	                    <Button
140	                        type="submit"
141	                        loading={isSaving}
142	                        disabled={!form.isDirty()}
143	                    >
144	                        Save
145	                    </Button>
146	                </Flex>
147	            </Paper>
148	        </Box>
149	    );
150	};
