1	import type { Metadata } from 'next';
2	import { notFound, permanentRedirect } from 'next/navigation';
3	import { cache } from 'react';
4	import z from 'zod';
5	
6	import { setGameResult } from '@/actions/setGameResult';
7	import { AutoRefresh } from '@/components/AutoRefresh/AutoRefresh';
8	import { GameDaySummary } from '@/components/GameDaySummary/GameDaySummary';
9	import { getUserRole } from '@/lib/auth.server';
10	import { formatDate } from '@/lib/dates';
11	import gameDayService from '@/services/GameDay';
12	import outcomeService from '@/services/Outcome';
13	import { FootyChannel } from '@/types/FootyChannel';
14	
15	interface PageProps {
16	    params: Promise<{ id: string }>;
17	}
18	
19	/**
20	 * Unpacks and validates route parameters for the game detail page.
21	 *
22	 * Validates the `id` parameter as a positive integer, retrieves the
23	 * corresponding game day, and handles redirects to the canonical URL if needed.
24	 *
25	 * @param params - The route parameters object containing the `id` property
26	 * @returns A promise that resolves to an object containing the validated
27	 * `gameDay`
28	 * @throws Calls `notFound()` if the game day cannot be found or the ID is
29	 * invalid
30	 * @throws Calls `permanentRedirect()` if the current URL doesn't match the
31	 * canonical URL
32	 */
33	const unpackParams = cache(async (params: PageProps['params']) => {
34	    const { id } = await params;
35	
36	    const gameDayId = z.coerce.number().int().min(1).safeParse(id);
37	    const gameDay = gameDayId.success
38	        ? await gameDayService.get(gameDayId.data)
39	        : undefined;
40	    if (!gameDay) notFound();
41	
42	    const canonicalUrl = `/footy/game/${gameDay.id}`;
43	    const currentUrl = `/footy/game/${id}`;
44	    if (currentUrl !== canonicalUrl) permanentRedirect(canonicalUrl);
45	
46	    return { gameDay };
47	});
48	
49	/**
50	 * Generates metadata for a game page.
51	 * @param props - The page props containing route parameters
52	 * @param props.params - Route parameters including the game ID
53	 * @returns A promise that resolves to metadata with the game title and date
54	 */
55	export async function generateMetadata(props: PageProps): Promise<Metadata> {
56	    const { gameDay } = await unpackParams(props.params);
57	
58	    return {
59	        title: formatDate(gameDay.date),
60	    };
61	}
62	
63	/**
64	 * Displays a football game day page with game details, team information, and
65	 * navigation.
66	 *
67	 * This is an async Server Component that fetches game data, determines user
68	 * role, and renders game results, player teams, and administrative controls
69	 * based on permissions.
70	 *
71	 * @component
72	 * @param {PageProps} props - The page component props
73	 * @param {object} props.params - Route parameters containing the game ID
74	 * @returns {Promise<React.ReactElement>} A flex container with game navigation,
75	 * admin controls, and game summary
76	 *
77	 * @remarks
78	 * - Fetches previous and next game days for navigation
79	 * - Retrieves team rosters (up to 10 players per team) for the current game day
80	 * - Calculates game winners from team data
81	 * - Only displays the GameResultForm if the user has an 'admin' role
82	 * - Navigation links (Previous/Next) are conditionally rendered based on data
83	 *   availability
84	 *
85	 * @requires getUserRole - To determine user permissions
86	 * @requires unpackParams - To extract gameDay from route params
87	 * @requires gameDayService.getPrevious - To fetch previous game
88	 * @requires gameDayService.getNext - To fetch next game
89	 * @requires outcomeService.getTeamPlayersByGameDay - To fetch team rosters
90	 * @requires getGameWinnersFromTeams - To calculate match winners
91	 */
92	const GamePage = async (props: PageProps) => {
93	    const { gameDay } = await unpackParams(props.params);
94	    const [role, prevGameDay, nextGameDay, teamA, teamB] = await Promise.all([
95	        getUserRole(),
